// DEVELOPMENT ONLY — the Phase 5 collaboration journey on FICTIONAL data.
//
// Routed only when import.meta.env.DEV (never in a production build). The data
// is src/components/collaboration/everestPreview.json, generated by
// `npm run dev:collab` from the real pure modules with a simulated ledger and a
// recorded ATLAS outcome. It is labelled as simulated on every screen; it must
// never be mistaken for live customer intelligence.
import { useState } from 'react';
import { CollaborationBoardView } from '@/components/collaboration/CollaborationBoardView';
import preview from '@/components/collaboration/everestPreview.json';
import type { CollaborationBoard } from '../../../supabase/functions/_shared/collab/board';

interface Preview {
  customer: string;
  steps: Array<{ label: string; note: string; board: CollaborationBoard }>;
  atlas_request: { query: string };
  lyra_draft: { title: string; body: string; needs_confirmation: string[]; status: string };
  brain_proposal: { fact_key: string; status: string; value: Record<string, unknown> } | null;
}
const data = preview as unknown as Preview;

export default function CollaborationPreview() {
  const [step, setStep] = useState(data.steps.length - 1);
  const s = data.steps[step];
  return (
    <div className="relative z-10 min-h-screen bg-[#0B0C0E]"><div className="mx-auto max-w-4xl space-y-4 p-4 text-[#ECE9E4] sm:p-6" data-testid="collaboration-preview">
      <div className="rounded-lg border border-amber-300/40 bg-amber-300/10 px-3 py-2 text-sm text-amber-100" role="note" data-testid="simulated-banner">
        Simulated preview — fictional companies, a simulated handoff ledger and a recorded ATLAS outcome. No provider was called and this is not live customer intelligence.
      </div>
      <header>
        <h1 className="text-xl font-semibold">AI workforce collaboration</h1>
        <p className="text-sm text-muted-foreground">Customer: {data.customer}</p>
      </header>
      <nav className="flex flex-wrap gap-2" aria-label="Journey steps">
        {data.steps.map((st, i) => (
          <button key={st.label} type="button" onClick={() => setStep(i)} data-testid={`step-${i + 1}`}
            className={`rounded-full border px-3 py-1 text-xs ${i === step ? 'border-sky-300 bg-sky-300/15' : 'border-white/15 hover:border-white/30'}`}>
            {st.label}
          </button>
        ))}
      </nav>
      <p className="text-sm" data-testid="step-note">{s.note}</p>
      <CollaborationBoardView board={s.board} />
      {step === data.steps.length - 1 && (
        <section className="grid gap-3 sm:grid-cols-2">
          <div className="rounded-xl border border-white/10 p-3 text-sm" data-testid="lyra-draft">
            <h2 className="mb-1 font-semibold">LYRA draft — {data.lyra_draft.status}</h2>
            <pre className="whitespace-pre-wrap text-xs">{data.lyra_draft.body}</pre>
            {data.lyra_draft.needs_confirmation.length > 0 && (
              <p className="mt-2 text-xs text-amber-200">Needs confirmation before publishing: {data.lyra_draft.needs_confirmation.join(' ')}</p>
            )}
          </div>
          <div className="space-y-3">
            <div className="rounded-xl border border-white/10 p-3 text-sm" data-testid="atlas-plan">
              <h2 className="mb-1 font-semibold">ATLAS plan (prefilled; launching it is a separate approval)</h2>
              <p className="text-xs">{data.atlas_request.query}</p>
            </div>
            {data.brain_proposal && (
              <div className="rounded-xl border border-white/10 p-3 text-sm" data-testid="brain-proposal">
                <h2 className="mb-1 font-semibold">Company Brain proposal — {data.brain_proposal.status}</h2>
                <p className="text-xs">{data.brain_proposal.fact_key}: {String(data.brain_proposal.value.fit)} — {String(data.brain_proposal.value.reason)}</p>
              </div>
            )}
          </div>
        </section>
      )}
    </div></div>
  );
}
